const cmd = `ruby -ryaml -rjson -e '
items = Dir[".archon-horizon/inbox/local/items/I-*.yaml"].map { |f| YAML.load_file(f) }
open = items.select { |x| x["status"] == "open" }
counts = open.group_by { |x| x["kind"] }.transform_values(&:length)
pick = ->(x) { {"id"=>x["id"], "kind"=>x["kind"], "title"=>x["body"].to_s.split("\\n",2)[0], "author"=>x["author"], "audience"=>x["audience"], "owner_task"=>x["owner_task"] || x.dig("metadata","owner_task"), "started_by"=>x.dig("metadata","started_by"), "created_at"=>x["created_at"], "updated_at"=>x["updated_at"]} }
out = {"counts"=>counts, "non_protection"=>open.count{|x| x["kind"]!="protection"}, "memories"=>open.select{|x| x["kind"]=="memory"}.map(&pick), "conversations"=>open.select{|x| x["kind"]=="conversation"}.map(&pick), "other"=>open.select{|x| !["memory","conversation","protection"].include?(x["kind"])}.map(&pick)}
puts JSON.pretty_generate(out)
'`;
